effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float n = max(levels, 2.0) - 1.0;
  vec3 q;
  if (mono){ float l = floor(gmLum(c) * n + 0.5) / n; q = vec3(l); }
  else { q = floor(c * n + 0.5) / n; }
  vec3 col = mix(c, q, mixAmt);
  gl_FragColor = vec4(col * a, a);
}
